import{z as A,x as d,o as t,c as i,q as n,j as l,D as e,d as o,s as B,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"TLB shootdown","description":"","frontmatter":{"title":"TLB shootdown","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tlb-shootdown.md","filePath":"cs/tlb-shootdown.md","lastUpdated":1791063341000}'),p={name:"cs/tlb-shootdown.md"};function h(m,a,D,I,P,C){const s=d("Mermaid");return t(),i("div",null,[a[2]||(a[2]=n('<h1 id="tlb-shootdown" tabindex="-1">TLB shootdown <a class="header-anchor" href="#tlb-shootdown" aria-label="Permalink to &quot;TLB shootdown&quot;">​</a></h1><div class="epigraph"><p>页表改了只保证本 CPU 看见新翻译；其他核的 TLB 仍可能缓存旧的 VPN→PPN，必须显式作废。</p><footer>—— 据 Black et al. 对 MACH 多处理器 TLB 一致性的讨论；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/huge-pages">上一课</a>让一条 TLB 项覆盖更大块。<a href="/cs/tlb-translate">TLB</a> 是每核私有的旁视缓冲，不是共享页表本身。<a href="/cs/page-fault-path">缺页路径</a>在本 CPU 填表并局部冲 TLB。缺口是<strong>多核</strong>：解映射、改权限、拆大页之后，别的核若仍用旧项，会写出已不属于该进程的物理页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>页表在内存里，改 PTE 对所有核「最终」可见，但 TLB 是各核 SRAM 副本。没有总线嗅探来自动丢翻译项。缺口不是再讲 ASID，而是：发起核发出核间中断（IPI），请其他核执行 <code>invlpg</code> 或冲本进程的一组项，并等待它们做完——这叫 shootdown。范围过大则变成全核风暴；过小则漏冲。</p><p><span class="marginnote">数字实例：一次 TLB 命中在纳秒级，而一次 IPI 从发出、目标核中断进出到应答，常常以微秒计——差三个数量级以上。几十核机器上 munmap 一段被广泛共享的映射，能打出几十次 shootdown 中断，开销立刻可测。</span></p><p>本课不把每种 ISA 的 INVLPG 编码写完。</p><p><span class="marginnote">惰性 shootdown：记下「世代」，核回到该进程时再冲。降低 IPI，换来短暂的过期翻译窗口，必须与 ASID/PCID 或「该页已不可写」等约束搭配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解映射：锁页表，清有效位，对本 CPU 冲 TLB，向持有该 mm 的 CPU 集发 IPI。各核在中断里冲指定 VA 或整张用户 TLB，应答。发起者等到齐再复用物理帧——否则 DMA 或别核 store 仍打旧帧。大页 shootdown 按大页基址作废。</p>',10)),(t(),l(r,null,{default:e(()=>[B(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNMAP%5B%22%E6%B8%85%20PTE%22%5D%20--%3E%20IPI%5B%22IPI%20%E9%80%9A%E7%9F%A5%E6%8C%81%E6%9C%89%E8%AF%A5%20mm%20%E7%9A%84%E6%A0%B8%22%5D%0A%20%20IPI%20--%3E%20INV%5B%22%E5%90%84%E6%A0%B8%20invlpg%20%2F%20%E5%86%B2%20ASID%22%5D%0A%20%20INV%20--%3E%20WAIT%5B%22%E7%AD%89%E9%BD%90%E5%90%8E%E5%86%8D%E5%A4%8D%E7%94%A8%E5%B8%A7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[o("shootdown 把 "),E("a",{href:"/cs/tlb-translate"},"TLB"),o(" 从「单核加速」接到「多核正确性」：它是虚存的一致性协议，对象是翻译，不是数据 Cache 行（数据一致性仍走 MESI 课）。频繁 "),E("code",null,"mprotect"),o("、munmap、大页拆分会让 IPI 成为可测的开销，于是有范围聚合与惰性策略。")],-1)),(t(),l(r,null,{default:e(()=>[B(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E9%A1%B5%E6%98%A0%E5%B0%84%E5%8D%B3%E5%B0%86%E5%8F%98%E6%9B%B4%22%5D%20--%3E%20S%7B%22%E9%80%89%E5%93%AA%E7%A7%8D%20shootdown%20%E7%AD%96%E7%95%A5%22%7D%0A%20%20S%20--%3E%7C%22%E7%AB%8B%E5%8D%B3%22%7C%20IM%5B%22%E5%8F%91%20IPI%2C%E7%AD%89%E6%89%80%E6%9C%89%E6%A0%B8%E5%86%B2%E5%AE%8C%22%5D%0A%20%20IM%20--%3E%20SAFE%5B%22%E5%AE%89%E5%85%A8%2C%E4%BD%86%E6%AF%8F%E6%AC%A1%E5%8F%98%E6%9B%B4%E9%83%BD%E4%BB%98%E4%B8%AD%E6%96%AD%E5%BC%80%E9%94%80%22%5D%0A%20%20S%20--%3E%7C%22%E6%83%B0%E6%80%A7%22%7C%20LA%5B%22%E5%8F%AA%E8%AE%B0%E4%B8%96%E4%BB%A3%2C%E5%9B%9E%E5%88%87%E6%97%B6%E5%86%8D%E5%86%B2%22%5D%0A%20%20LA%20--%3E%20WIN%5B%22%E7%9C%81%20IPI%2C%E4%BD%86%E8%A6%81%E6%8E%A5%E5%8F%97%E8%BF%87%E6%9C%9F%E7%BF%BB%E8%AF%91%E7%AA%97%E5%8F%A3%22%5D%0A%20%20S%20--%3E%7C%22%E8%8C%83%E5%9B%B4%E8%81%9A%E5%90%88%22%7C%20RA%5B%22%E6%94%92%E4%B8%80%E6%89%B9%E5%8F%98%E6%9B%B4%2C%E5%90%88%E5%B9%B6%E6%88%90%E4%B8%80%E6%AC%A1%E5%86%B2%22%5D%0A%20%20RA%20--%3E%20AMP%5B%22%E5%9D%87%E6%91%8A%E5%BC%80%E9%94%80%2C%E6%89%B9%E5%86%85%E5%9C%B0%E5%9D%80%E6%9A%82%E4%B8%8D%E5%8F%AF%E5%A4%8D%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">术语翻译：shootdown 字面意思是「把飞行物打下来」。页表改完，别的核 TLB 里那枚旧 VPN→PPN 还在「天上飞」——不主动打下它，接下来的访存还会落回已经被抢走的物理帧。名字夸张，说的正是「必须显式作废」这件事。</span></p><p>不要把页表 walker 再推一遍：walker 读的是内存中的新 PTE；错误来自旁路缓冲。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 x86 PCID 与 INVPCID 的全部优化表。不把 GPU 的自己的 TLB 写进主干。内核映射全局项（用户/内核分裂里的高半）改动更危险，通常极少改或用专门全局冲。下一课假设：帧要被抢走时，翻译已经到处作废。</p><p>后课默认：解映射在多核上可完成。无空闲帧时淘汰谁、如何选牺牲页，下一课缺页与置换。</p><p><span class="marginnote">常见误区：初学者容易以为硬件缓存一致性（MESI 那类协议）会顺带把 TLB 也同步了。实际 MESI 管的是数据 Cache 行；TLB 是旁视结构，不在嗅探范围内，翻译过期只能靠指令或 IPI 显式作废——这正是 shootdown 存在的理由。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>改 PTE 后必须 shootdown 他核 TLB，才能复用帧。</li><li>IPI 是开销；惰性与范围聚合是实现。</li><li>无帧时的淘汰算法是置换课的缺口。</li><li>出处：Black et al. 对 MACH TLB；Love, <em>LKD</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const u=A(p,[["render",h]]);export{c as __pageData,u as default};
